using System;
using System.IO;
using System.Reflection;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;

public class CombatRailIntegrationTests {
 static BasicCombatSimulation ArtilleryFresh(){var train=new BasicCombatActor("train",false,true,false,0,10000,0,0,1000,0,0,BasicCombatTarget.EnemyExterior,10000);var waves=new BasicCombatActor[4][];for(int i=0;i<4;i++)waves[i]=new[]{new BasicCombatActor("e"+i,true,false,false,0,1000,0,0,1000,0,0,BasicCombatTarget.Train,0)};var s=new BasicCombatSimulation("rail-gun-test",500000,1,new[]{train},waves);var c=CombatRailJourneyTests.Config();var art=CombatRailArtilleryTests.Config();art["encounters"][0]["spawnWave"]=1;c["artillery"]=art;s.ConfigureRailJourney(c);return s;}
 [Test] public void ArtilleryIsDistinctFocusableActorAndImpactsExistingShield(){var s=ArtilleryFresh();s.Advance(500000,8);Assert.IsTrue(s.SetEnemyFocus("gun-2"));s.ApplyResolvedShield("train",new CombatShieldSource("train","test-shield",0),100,1000);for(int i=0;i<21;i++)s.Advance(500000,8);Assert.AreEqual(10000,s.GetHp("train"));Assert.That(s.Events,System.Linq.Enumerable.Any<BasicCombatHit>(s.Events,x=>x.Source=="gun-2"&&x.Absorbed==50)?Is.Not.Null:Is.Null,"Actual artillery impact should consume shield");var saved=s.CaptureLocalState();Assert.AreEqual(saved,BasicCombatSimulation.RestoreLocalState(saved,ArtilleryFresh).CaptureLocalState());}
 static object Call(object target,string name,params object[] args){var method=target.GetType().GetMethod(name);Assert.NotNull(method,"Missing integration: "+name);try{return method.Invoke(target,args);}catch(TargetInvocationException e){throw e.InnerException;}}
 static BasicCombatSimulation Base(){var train=new BasicCombatActor("train",false,true,false,0,10000,10,0,1,0,0,BasicCombatTarget.EnemyAny,10000);var waves=new BasicCombatActor[4][];for(int i=0;i<4;i++)waves[i]=new[]{new BasicCombatActor("e"+i,true,false,false,0,1,0,0,1000,0,0,BasicCombatTarget.Train,0)};return new BasicCombatSimulation("rail-test",500000,1,new[]{train},waves);}
 static BasicCombatSimulation Fresh(){var s=Base();var c=CombatRailJourneyTests.Config();c["offers"][0]["afterCompletedWaves"]=1;Call(s,"ConfigureRailJourney",c);return s;}
 [Test] public void SelectionHoldsNextWaveAndRestoresWithoutDebtBurst(){var s=Fresh();s.SetSpeed(4);s.Advance(500000,8);var pending=JObject.Parse(s.CaptureLocalState());Assert.AreEqual("Selecting",(string)pending["railJourney"]["phase"]);Assert.AreEqual(1,s.CompletedWaves);var distance=(long)pending["railJourney"]["distanceMm"];for(int i=0;i<300;i++)s.Advance(1000000,8);Assert.AreEqual(1,s.CompletedWaves,"Waiting must not spawn or complete following waves");Assert.AreEqual(distance,(long)JObject.Parse(s.CaptureLocalState())["railJourney"]["distanceMm"]);var restored=BasicCombatSimulation.RestoreLocalState(s.CaptureLocalState(),Fresh);Assert.AreEqual(s.CaptureLocalState(),restored.CaptureLocalState());Call(restored,"ConfirmRailRoute","fork-3","left");Assert.Less(restored.PendingSteps,1);Assert.AreEqual(4,(int)restored.ReadHudState()["speedHalfUnits"]);Assert.Throws<ArgumentException>(()=>BasicCombatSimulation.RestoreLocalState(restored.CaptureLocalState(),Base));Assert.Throws<ArgumentException>(()=>BasicCombatSimulation.RestoreLocalState(Base().CaptureLocalState(),Fresh));}
 [Test] public void SaveFailureCannotPublishConfirmation(){string saved=null;bool fail=false;var d=new CombatSceneDriver(Fresh,()=>null,(s,r)=>{if(fail)throw new IOException("injected");saved=s.CaptureLocalState();return r+1;},()=>true);d.Open();d.Advance(500000,8);string before=d.StateJson;fail=true;Assert.Throws<IOException>(()=>Call(d,"ConfirmRailRoute","fork-3","left"));Assert.AreEqual(before,d.StateJson);Assert.AreEqual(before,saved);Assert.IsTrue(d.RecoveryRequired);}
 [Test] public void ConfirmationDoesNotChangeImmutableConfigurationAndPauseStopsRecovery(){var s=Fresh();s.Advance(500000,8);var before=JObject.Parse(s.CaptureLocalState());Call(s,"ConfirmRailRoute","fork-3","right");Assert.AreEqual((string)before["configurationSha256"],(string)JObject.Parse(s.CaptureLocalState())["configurationSha256"]);s.SetPaused(true);string paused=s.CaptureLocalState();s.Advance(10000000,8);Assert.AreEqual(paused,s.CaptureLocalState());var restored=BasicCombatSimulation.RestoreLocalState(paused,Fresh);Assert.AreEqual(paused,restored.CaptureLocalState());}
}
